package dev.votex.client;
import dev.votex.arcade.ArcadeGames;
import dev.votex.ui.WorkspaceLayout;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.input.KeyEvent;
import net.minecraft.client.input.MouseButtonEvent;
import net.minecraft.network.chat.Component;
import org.lwjgl.glfw.GLFW;
import java.util.*;
/** Four real games, entirely local. Simulation pauses immediately outside the focused window. */
public final class ArcadeScreen extends Screen implements VotexMenuSurface {
 private final VotexClient core;private final ArcadeGames.Pong pong=new ArcadeGames.Pong();private final ArcadeGames.TicTacToe tic=new ArcadeGames.TicTacToe();private final ArcadeGames.Flappy flappy=new ArcadeGames.Flappy();private final ArcadeGames.Tetris tetris=new ArcadeGames.Tetris();
 private static final int[] COLORS={0,0xff58d9ff,0xffffd85d,0xffb99aff,0xff69e8b2,0xffff7594,0xff67a3ff,0xffffb875};
 private final Set<Integer> keys=new HashSet<>();private String game="";private boolean paused,compact;private float scale=1;private int logicalW,logicalH,left,top,w,h,bx,by,bw,bh,tile;private double target=.5;private long last=System.nanoTime();
 public ArcadeScreen(VotexClient core){super(Component.literal("Votex Arcade"));this.core=core;}
 @Override public boolean isPauseScreen(){return false;}
 private GlassButton button(int x,int y,int width,int height,String title,String detail,Runnable press){return addRenderableWidget(new GlassButton(core,x,y,width,height,title,detail,()->false,b->press.run()));}
 @Override protected void init(){var layout=WorkspaceLayout.measure(width,height,minecraft.getWindow().getGuiScale());scale=layout.scale();logicalW=layout.logicalWidth();logicalH=layout.logicalHeight();w=Math.min(900,logicalW-40);h=Math.min(590,logicalH-36);compact=h<470;left=(logicalW-w)/2;top=(logicalH-h)/2;button(left+16,top+16,90,28,"‹ Zurück","",this::onClose);if(game.isEmpty()){int cardW=(w-54)/2,cardH=(h-124)/2;String[] names={"Pong","Tic-Tac-Toe","Flappy","Tetris"},details={"Präzision gegen die KI · bis 7 Punkte","Drei gewinnt · perfekte KI oder zu zweit","Ein Klick. Noch ein Tor. Dein Rekord.","Sieben Formen. Ganze Reihen. Flow."},ids={"PONG","TIC","FLAPPY","TETRIS"};for(int i=0;i<4;i++){String id=ids[i];button(left+18+i%2*(cardW+18),top+89+i/2*(cardH+16),cardW,cardH,names[i],details[i],()->select(id)).icon(switch(i){case 0->"performance";case 1->"modules";case 2->"emotes";default->"cube";});}return;}
  button(left+w-238,top+16,100,28,"Neu starten","",this::reset);button(left+w-126,top+16,108,28,"Pause / Weiter","",()->paused=!paused);bx=left+22;by=top+79;bw=w-44;bh=h-127;
  if(game.equals("TETRIS")){tile=Math.max(10,Math.min((bw-220)/10,bh/20));bw=tile*10;bh=tile*20;bx=left+(w-210-bw)/2;int row=compact?108:150,step=compact?34:38,buttonH=compact?26:30;button(bx+bw+24,by+row,64,buttonH,"Nach links","",()->tetris.move(-1)).icon("arrow_left").iconOnly();button(bx+bw+96,by+row,64,buttonH,"Nach rechts","",()->tetris.move(1)).icon("arrow").iconOnly();button(bx+bw+24,by+row+step,136,buttonH,"Drehen","",tetris::rotate).icon("refresh");button(bx+bw+24,by+row+step*2,136,buttonH,"Fallen lassen","",tetris::hardDrop);}
  if(game.equals("TIC")){int side=Math.min(bw-220,bh);tile=side/3;bw=bh=tile*3;button(bx+bw+26,by+90,170,34,tic.ai?"Zu zweit spielen":"Gegen KI spielen","",()->{tic.ai=!tic.ai;tic.reset();rebuildWidgets();});}
 }
 private void select(String id){game=id;reset();rebuildWidgets();}
 private void reset(){pong.reset();tic.reset();flappy.reset();tetris.reset();paused=false;keys.clear();target=.5;last=System.nanoTime();}
 private void step(){long now=System.nanoTime();double dt=Math.min(.05,(now-last)/1_000_000_000d);last=now;if(!minecraft.isWindowActive()){keys.clear();return;}if(paused||game.isEmpty())return;if(game.equals("PONG")){int vertical=(keys.contains(GLFW.GLFW_KEY_DOWN)||keys.contains(GLFW.GLFW_KEY_S)?1:0)-(keys.contains(GLFW.GLFW_KEY_UP)||keys.contains(GLFW.GLFW_KEY_W)?1:0);target=Math.clamp(target+vertical*1.3*dt,.1,.9);pong.update(dt,target);}else if(game.equals("FLAPPY"))flappy.update(dt);else if(game.equals("TETRIS"))tetris.update(dt,keys.contains(GLFW.GLFW_KEY_DOWN));}
 @Override public void extractBackground(GuiGraphicsExtractor g,int mx,int my,float delta){if(core.modules.config().blurMenus&&core.theme.blur())extractBlurredBackground(g);g.fill(0,0,width,height,0x48060b16);}
 @Override public void extractRenderState(GuiGraphicsExtractor g,int mx,int my,float delta){step();int x=Math.round(mx/scale),y=Math.round(my/scale);g.pose().pushMatrix();g.pose().scale(scale,scale);GlassRender.panel(g,left,top,w,h,core.theme);String heading=game.isEmpty()?"Votex Arcade":switch(game){case "TIC"->"Tic-Tac-Toe";case "FLAPPY"->"Flappy";case "TETRIS"->"Tetris";default->"Pong";};int headingX=left+(game.isEmpty()?w/2:(w-132)/2);UiText.title(g,heading,headingX-Math.round(UiText.titleWidth(heading)*.625f),top+22,core.theme.text(),1.25f);if(game.isEmpty()){UiText.centered(g,"Eine kleine Pause. Direkt in deinem Client.",logicalW/2,top+58,core.theme.muted());}else{GlassRender.round(g,bx-2,by-2,bw+4,bh+4,12,0xb0060d19);g.enableScissor(bx,by,bx+bw,by+bh);switch(game){case "PONG"->drawPong(g);case "TIC"->drawTic(g);case "FLAPPY"->drawFlappy(g);case "TETRIS"->drawTetris(g);}g.disableScissor();if(game.equals("TETRIS"))drawTetrisInfo(g);if(game.equals("TIC"))drawTicInfo(g);String controls=switch(game){case "PONG"->"Maus oder W/S · Erreiche zuerst 7 Punkte";case "TIC"->"Feld anklicken · Drei in einer Reihe gewinnen";case "FLAPPY"->"Leertaste oder Klick · R startet neu";default->"Pfeile bewegen/drehen · Unten beschleunigt · Leertaste fallen lassen";};UiText.centered(g,UiText.fit(controls,w-44),logicalW/2,top+h-29,core.theme.muted());if(paused||!minecraft.isWindowActive())message(g,"Pausiert",minecraft.isWindowActive()?"Pause / Weiter zum Fortsetzen":"Fenster aktivieren zum Fortsetzen");}super.extractRenderState(g,x,y,delta);g.pose().popMatrix();}
 private void drawPong(GuiGraphicsExtractor g){for(int yy=by+8;yy<by+bh;yy+=18)GlassRender.round(g,bx+bw/2-1,yy,2,8,1,0x484e7195);int paddleW=Math.max(6,(int)(bw*.018));GlassRender.round(g,bx+(int)(bw*.04),(int)(by+(pong.left-.10)*bh),paddleW,(int)(bh*.2),4,core.theme.accent());GlassRender.round(g,bx+(int)(bw*.942),(int)(by+(pong.right-.10)*bh),paddleW,(int)(bh*.2),4,0xffb6d3ec);GlassRender.round(g,bx+(int)(pong.ballX*bw)-5,by+(int)(pong.ballY*bh)-5,10,10,5,0xffe5f5ff);UiText.title(g,Integer.toString(pong.playerScore),bx+bw/2-65,by+16,core.theme.text(),2);UiText.title(g,Integer.toString(pong.aiScore),bx+bw/2+40,by+16,core.theme.text(),2);if(pong.over)message(g,pong.playerScore>=7?"Gewonnen!":"Gute Runde","Neu starten für eine Revanche");}
 private void drawTic(GuiGraphicsExtractor g){for(int i=0;i<9;i++){int xx=bx+i%3*tile,yy=by+i/3*tile;GlassRender.round(g,xx+3,yy+3,tile-6,tile-6,12,0x85213952);if(tic.board[i]!=0){int size=Math.min(48,tile-20);GlassRender.icon(g,tic.board[i]==1?"close":"circle",xx+(tile-size)/2,yy+(tile-size)/2,size,tic.board[i]==1?core.theme.accent():0xff7ce2bd);}}}
 private void drawTicInfo(GuiGraphicsExtractor g){String text=tic.winner==3?"Unentschieden":tic.winner!=0?(tic.winner==1?"X gewinnt":"O gewinnt"):(tic.turn==1?"X ist am Zug":"O ist am Zug");UiText.draw(g,text,bx+bw+26,by+28,core.theme.text());UiText.draw(g,tic.ai?"Du spielst X. Die KI spielt O.":"Zwei Spieler an einem Gerät.",bx+bw+26,by+52,core.theme.muted());}
 private void drawFlappy(GuiGraphicsExtractor g){for(int i=0;i<flappy.pipes.length;i++){int x=bx+(int)(flappy.pipes[i]*bw),pipeW=(int)(bw*.09),gapTop=by+(int)((flappy.gaps[i]-.16)*bh),gapBottom=by+(int)((flappy.gaps[i]+.16)*bh);GlassRender.round(g,x,by,pipeW,gapTop-by,8,0xff2e657b);GlassRender.round(g,x,gapBottom,pipeW,by+bh-gapBottom,8,0xff2e657b);}int birdX=bx+(int)(.24*bw),birdY=by+(int)(flappy.bird*bh);GlassRender.round(g,birdX-9,birdY-8,18,16,6,core.theme.accent());g.fill(birdX+3,birdY-3,birdX+6,birdY,0xfff6fbff);UiText.title(g,Integer.toString(flappy.score),bx+bw/2,by+15,core.theme.text(),2);if(!flappy.started)message(g,"Bereit zum Fliegen?","Leertaste oder Klick");if(flappy.over)message(g,"Runde beendet · "+flappy.score+" Punkte","R oder Neu starten");}
 private void drawTetris(GuiGraphicsExtractor g){for(int row=0;row<20;row++)for(int col=0;col<10;col++){int value=tetris.board[row][col];GlassRender.round(g,bx+col*tile+1,by+row*tile+1,tile-2,tile-2,Math.max(1,tile/6),value==0?0x282f4665:COLORS[value]);}if(!tetris.over){int ghost=tetris.ghostY();for(int i=0;i<4;i++){int x=bx+(tetris.x+tetris.cellX(i,tetris.rotation))*tile,y=by+(ghost+tetris.cellY(i,tetris.rotation))*tile;GlassRender.border(g,x+1,y+1,tile-2,tile-2,Math.max(1,tile/6),0x90789bb5);y=by+(tetris.y+tetris.cellY(i,tetris.rotation))*tile;GlassRender.round(g,x+1,y+1,tile-2,tile-2,Math.max(1,tile/6),COLORS[tetris.type+1]);}}else message(g,"Runde beendet","Neu starten für eine neue Runde");}
 private void drawTetrisInfo(GuiGraphicsExtractor g){int x=bx+bw+24;UiText.draw(g,"Punkte",x,by+(compact?4:8),core.theme.muted());UiText.title(g,Integer.toString(tetris.score),x,by+(compact?22:27),core.theme.text(),1.6f);UiText.draw(g,"Reihen   "+tetris.lines,x,by+(compact?48:61),core.theme.text());UiText.draw(g,"Level     "+(1+tetris.lines/10),x,by+(compact?66:83),core.theme.text());UiText.draw(g,"Nächste Form: "+new String[]{"I","O","T","S","Z","J","L"}[tetris.next],x,by+(compact?84:112),COLORS[tetris.next+1]);}
 private void message(GuiGraphicsExtractor g,String heading,String detail){int ww=Math.min(bw-16,340),xx=bx+(bw-ww)/2,yy=by+bh/2-32;GlassRender.round(g,xx,yy,ww,66,13,0xec142339);UiText.centered(g,UiText.fit(heading,ww-16),xx+ww/2,yy+17,core.theme.text());UiText.centered(g,UiText.fit(detail,ww-16),xx+ww/2,yy+39,core.theme.muted());}
 @Override public void mouseMoved(double x,double y){if(game.equals("PONG"))target=Math.clamp((y/scale-by)/bh,.1,.9);super.mouseMoved(x,y);}
 @Override public boolean mouseClicked(MouseButtonEvent e,boolean twice){var logical=new MouseButtonEvent(e.x()/scale,e.y()/scale,e.buttonInfo());if(super.mouseClicked(logical,twice))return true;if(e.button()!=0||paused||!minecraft.isWindowActive())return false;if(game.equals("FLAPPY")&&logical.x()>=bx&&logical.x()<bx+bw&&logical.y()>=by&&logical.y()<by+bh){flappy.flap();return true;}if(game.equals("TIC")&&logical.x()>=bx&&logical.x()<bx+bw&&logical.y()>=by&&logical.y()<by+bh){tic.play((int)((logical.y()-by)/tile)*3+(int)((logical.x()-bx)/tile));return true;}return false;}
 @Override public boolean mouseReleased(MouseButtonEvent e){return super.mouseReleased(new MouseButtonEvent(e.x()/scale,e.y()/scale,e.buttonInfo()));}
 @Override public boolean keyPressed(KeyEvent e){if(e.key()==GLFW.GLFW_KEY_ESCAPE){onClose();return true;}if(game.isEmpty())return super.keyPressed(e);if(e.key()==GLFW.GLFW_KEY_R){reset();return true;}if(e.key()==GLFW.GLFW_KEY_P){paused=!paused;return true;}if(paused)return true;keys.add(e.key());if(game.equals("FLAPPY")&&e.key()==GLFW.GLFW_KEY_SPACE){flappy.flap();return true;}if(game.equals("TETRIS")){switch(e.key()){case GLFW.GLFW_KEY_LEFT->tetris.move(-1);case GLFW.GLFW_KEY_RIGHT->tetris.move(1);case GLFW.GLFW_KEY_UP,GLFW.GLFW_KEY_X->tetris.rotate();case GLFW.GLFW_KEY_SPACE->tetris.hardDrop();default->{return super.keyPressed(e);}}return true;}return game.equals("PONG")||super.keyPressed(e);}
 @Override public boolean keyReleased(KeyEvent e){keys.remove(e.key());return super.keyReleased(e);}
 @Override public void onClose(){keys.clear();if(!game.isEmpty()){game="";paused=false;rebuildWidgets();}else minecraft.gui.setScreen(new VotexScreen(core,"HOME"));}
}
